using System.IO;
using System.Text.Json;
using HyperLib.Core;

namespace Hypershell.Services;

/// <summary>Small, independent, editable building blocks; no network dependencies or form backends.</summary>
public static class HyperlibFoundationCatalog
{
    private sealed record Module(string Id, string Title, string Category, string Description, string Markup,
        string Items = "First item|A useful detail\nSecond item|Another useful detail\nThird item|One more detail", string Code = "");

    public static async Task EnsureAsync(string root, CancellationToken ct = default)
    {
        foreach (var family in Modules.GroupBy(x => x.Category))
        {
            var id = "foundation-" + family.Key.ToLowerInvariant().Replace(' ', '-');
            if (Directory.Exists(Path.Combine(root, "CoreLibrary", "DesignGroups", id))) continue;
            var project = Path.Combine(root, "CoreLibrary", ".seeds", id, "Project");
            await TemplateProjectScaffolder.EnsureAsync(root, project, id, family.Key + " essentials", ct, starterId: "blank");
            var definition = StarterTemplate.Create();
            definition.Title = family.Key + " essentials";
            definition.TemplateId = id;
            definition.Blocks.Clear(); definition.DefaultBlocks.Clear(); definition.EmptyPageDefault = true;
            definition.Regions = [new() { Id = "main", Title = "Main content" }];
            foreach (var module in family)
            {
                var component = "Foundation" + string.Concat(module.Id.Split('-').Select(p => char.ToUpperInvariant(p[0]) + p[1..])) + "Block";
                definition.Blocks.Add(new BlockDefinition
                {
                    Id = module.Id, Title = module.Title, Component = component,
                    CatalogId = "HLC-FOUNDATION-" + module.Id.ToUpperInvariant(), Category = family.Key,
                    Description = module.Description, SourceLibrary = "Hyperlib Foundations", SourceTemplateId = id,
                    Fields = [Field("title", "Heading", "string", module.Title), Field("text", "Description", "text", module.Description),
                        Field("items", "Items (one per line; separate columns with |)", "text", module.Items),
                        Field("url", "Destination", "url", "/"), Field("label", "Link or action label", "string", "Explore more")]
                });
                var source = "@namespace HyperLib.Work\n@using System.Globalization\n<section class=\"catalog-module module-" + module.Id + "\">\n" + module.Markup + "\n</section>\n@code {\n [Parameter, EditorRequired] public BlockContext Context { get; set; } = new();\n private string[] Rows => Context.Text(\"items\").Split('\\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);\n private static string Cell(string row, int index) => row.Split('|').ElementAtOrDefault(index)?.Trim() ?? \"\";\n" + module.Code + "\n}\n";
                var folder = Path.Combine(project, "src", "Pages", "Blocks"); Directory.CreateDirectory(folder);
                await File.WriteAllTextAsync(Path.Combine(folder, component + ".razor"), source, ct);
                await File.WriteAllTextAsync(Path.Combine(folder, component + ".razor.css"), Css, ct);
            }
            TemplateValidator.ValidateDefinition(definition);
            await File.WriteAllTextAsync(Path.Combine(project, "authoring.template.json"), JsonSerializer.Serialize(definition, ContentJson.Options), ct);
            await TemplateObjectLibrary.RegisterDesignGroupAsync(root, project, id, definition.Title,
                "Editable " + family.Key.ToLowerInvariant() + " modules. Native controls and local C# interactions; no third-party service required.", family.Key, id, ct);
        }
    }

    private static FieldDefinition Field(string id, string title, string type, string value)
        => new() { Id = id, Title = title, Type = type, DefaultValue = ContentJson.Value(value) };

    private const string Heading = "<header><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></header>";
    private const string Link = "<a class=\"action\" href=\"@Context.Text(\"url\")\">@Context.Text(\"label\") <span aria-hidden=\"true\">↗</span></a>";
