        new("aside-note", "Editorial aside", "Structure", "A secondary note with a clear label and quieter typography.", "<aside class=\"aside-note\"><p class=\"kicker\">@Context.Text(\"title\")</p><p>@Context.Text(\"text\")</p>" + Link + "</aside>"),
        new("section-heading", "Section heading", "Structure", "An eyebrow, heading, and rule establish a new part of the page.", "<header class=\"section-heading\"><p class=\"kicker\">@Cell(Rows.FirstOrDefault() ?? \"Section 01\",0)</p><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></header>", "Section 01"),
        new("profile-card", "Profile card", "Structure", "An identity panel with a short biography and links.", "<article class=\"profile panel\"><span class=\"avatar large\" aria-hidden=\"true\">✦</span><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p><ul class=\"pills\">@foreach(var row in Rows){<li><a href=\"@Context.Text(\"url\")\">@Cell(row,0)</a></li>}</ul></article>", "Portfolio\nJournal\nContact"),
        new("resource-card", "Resource card", "Structure", "A reference object with type, description, and an external destination.", "<article class=\"resource panel\"><p class=\"kicker\">Reference · @Cell(Rows.FirstOrDefault() ?? \"Guide\",0)</p><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p>" + Link + "</article>", "Guide"),
        new("newsletter-panel", "Newsletter panel", "Structure", "An invitation to follow a project, with a configurable destination.", "<aside class=\"newsletter panel\"><div><p class=\"kicker\">Occasional dispatches</p><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div>" + Link + "</aside>"),
        new("site-footer", "Multi-column footer", "Structure", "An adaptable footer for a small publication or product site.", "<footer><div class=\"parallel\"><div><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div><nav aria-label=\"Footer\"><ul>@foreach(var row in Rows){<li><a href=\"@Context.Text(\"url\")\">@Cell(row,0)</a></li>}</ul></nav></div><hr /><small>Made with care · @DateTime.UtcNow.Year</small></footer>", "About\nArchive\nContact\nAccessibility"),
        new("call-to-action", "Call to action", "Structure", "One focused invitation at the end of a section.", "<section class=\"call-to-action\"><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p>" + Link + "</section>"),

        new("ornamental-rule", "Ornamental rule", "Decoration", "A quiet typographic divider inspired by printed books.", "<div class=\"ornamental-rule\" role=\"separator\" aria-label=\"Section break\"><span>✦</span></div>"),
        new("corner-frame", "Corner frame", "Decoration", "Fine corner marks frame a short passage without a heavy border.", "<figure class=\"corner-frame\"><p>@Context.Text(\"text\")</p><figcaption>@Context.Text(\"title\")</figcaption></figure>"),
        new("edition-seal", "Edition seal", "Decoration", "A circular typographic badge for a series or edition.", "<div class=\"edition-seal\"><span>✦</span><strong>@Context.Text(\"title\")</strong><small>@Cell(Rows.FirstOrDefault() ?? \"EST. 2026\",0)</small></div>", "EST. 2026"),
        new("dot-grid", "Dot-grid panel", "Decoration", "A subtle repeating dot pattern beneath a readable content surface.", "<div class=\"dot-grid\"><div class=\"panel\"><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div></div>"),
        new("numbered-marker", "Numbered marker", "Decoration", "A bold sequence number paired with a compact label.", "<div class=\"numbered-marker\"><span>01</span><div><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div></div>"),
        new("ribbon-label", "Ribbon label", "Decoration", "A simple clipped label for an edition, feature, or notice.", "<div class=\"ribbon\">@Context.Text(\"title\")</div><p>@Context.Text(\"text\")</p>"),
        new("reading-progress", "Reading progress", "Decoration", "A labeled progress meter that can be connected to a document's reading position.", "<label class=\"reading-progress\"><span>@Context.Text(\"title\") <strong>Chapter 3 of 8</strong></span><progress value=\"3\" max=\"8\">3 of 8</progress></label>"),
        new("tag-cloud", "Tag cluster", "Decoration", "Small topic labels with wrapping that works at narrow widths.", "<ul class=\"tags\" aria-label=\"@Context.Text(\"title\")\">@foreach(var row in Rows){<li>@Cell(row,0)</li>}</ul>", "Architecture\nNature\nHistory\nSystems\nCraft\nExploration"),
        new("inset-paper", "Inset paper", "Decoration", "A lightly layered paper surface for a letter, note, or extract.", "<article class=\"inset-paper\"><p class=\"kicker\">@Context.Text(\"title\")</p><p>@Context.Text(\"text\")</p><small>@Cell(Rows.FirstOrDefault() ?? \"From the archive\",0)</small></article>", "From the archive"),
        new("accent-band", "Accent band", "Decoration", "A narrow full-width color field carrying a short statement.", "<aside class=\"accent-band\"><strong>@Context.Text(\"title\")</strong><span>@Context.Text(\"text\")</span></aside>"),

        new("empty-state", "Empty state", "Status", "Explain a blank area and offer one useful next step.", "<section class=\"empty-state\"><span aria-hidden=\"true\">◇</span><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p>" + Link + "</section>"),
        new("error-summary", "Error summary", "Status", "An accessible error group that lists the details to correct.", "<section class=\"notice error\" role=\"alert\"><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p><ul>@foreach(var row in Rows){<li>@Cell(row,0)</li>}</ul></section>", "Enter a valid email address\nChoose an appointment date"),
        new("success-notice", "Success notice", "Status", "A restrained success message with clear next-step copy.", "<section class=\"notice success\" role=\"status\"><span aria-hidden=\"true\">✓</span><div><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div></section>"),
        new("warning-note", "Warning note", "Status", "Draw attention to a relevant condition without interrupting the page.", "<aside class=\"notice warning\"><span aria-hidden=\"true\">!</span><div><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p></div></aside>"),
        new("loading-skeleton", "Loading skeleton", "Status", "A static loading placeholder that respects reduced-motion preferences.", "<div class=\"skeleton\" role=\"status\" aria-label=\"Loading content\"><div></div><p></p><p></p><p></p><span class=\"sr-only\">Loading content…</span></div>"),
        new("connection-status", "Connection status", "Status", "Pair a small status light with meaningful text and a timestamp label.", "<div class=\"connection-status panel\"><span class=\"status-dot\" aria-hidden=\"true\"></span><div><strong>@Context.Text(\"title\")</strong><p>@Context.Text(\"text\")</p></div><small>@Cell(Rows.FirstOrDefault() ?? \"Checked just now\",0)</small></div>", "Checked just now"),
        new("maintenance-panel", "Maintenance panel", "Status", "Explain a temporary interruption and make the alternative route clear.", "<section class=\"maintenance panel\"><p class=\"kicker\">A brief pause</p><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p>" + Link + "</section>"),
        new("revision-history", "Revision history", "Status", "A compact changelog with version labels and concise notes.", Heading + "<ol class=\"revisions\">@foreach(var row in Rows){<li><span class=\"badge\">@Cell(row,0)</span><div><strong>@Cell(row,1)</strong><p>@Cell(row,2)</p></div></li>}</ol>", "1.2|A clearer index|Added cross-references and topic labels\n1.1|More context|Expanded the examples\n1.0|First edition|The collection begins"),
        new("confirmation-panel", "Confirmation panel", "Status", "An inline confirmation pattern with reversible local state.", "<section class=\"panel\"><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p><div class=\"pills\"><button @onclick=\"()=>confirmed=true\">Confirm preview</button><button @onclick=\"()=>confirmed=false\">Reset</button></div><output aria-live=\"polite\">@(confirmed ? \"Confirmed locally. No external action was taken.\" : \"Waiting for confirmation.\")</output></section>", Code: "private bool confirmed;"),
        new("offline-note", "Offline note", "Status", "A small message explaining the availability of local content.", "<aside class=\"offline-note\"><span aria-hidden=\"true\">⌁</span><div><strong>@Context.Text(\"title\")</strong><p>@Context.Text(\"text\")</p></div></aside>"),

        new("flashcard", "Flashcard", "Learning", "A native disclosure keeps an answer hidden until the reader asks for it.", "<article class=\"flashcard panel\"><p class=\"kicker\">@Context.Text(\"title\")</p><h3>@Cell(Rows.FirstOrDefault() ?? \"What is a design system?|A shared vocabulary for building interfaces.\",0)</h3><details><summary>Reveal answer</summary><p>@Cell(Rows.FirstOrDefault() ?? \"Question|Answer\",1)</p></details></article>", "What is a design system?|A shared vocabulary of patterns, components, and decisions for building coherent interfaces."),
        new("learning-objectives", "Learning objectives", "Learning", "State the outcomes of a lesson in a compact, numbered sequence.", Heading + "<ol class=\"objectives\">@foreach(var row in Rows){<li>@Cell(row,0)</li>}</ol>", "Recognize the main parts of a system\nDescribe how those parts interact\nBuild and test a small example"),
        new("lesson-outline", "Lesson outline", "Learning", "Break a learning session into short, time-bounded stages.", Heading + "<ol class=\"lesson-outline\">@foreach(var row in Rows){<li><small>@Cell(row,0)</small><div><h3>@Cell(row,1)</h3><p>@Cell(row,2)</p></div></li>}</ol>", "5 min|Observe|Look closely at the example\n15 min|Make|Build a small variation\n10 min|Reflect|Compare the result with your intent"),
        new("experiment-record", "Experiment record", "Learning", "Document a hypothesis, method, and observation with explicit labels.", Heading + "<dl class=\"experiment\">@foreach(var row in Rows){<div><dt>@Cell(row,0)</dt><dd>@Cell(row,1)</dd></div>}</dl>", "Question|How does light affect growth?\nHypothesis|More light increases growth up to a threshold.\nMethod|Compare three matched groups over two weeks.\nObservation|Record height and leaf count each morning."),
        new("rubric", "Assessment rubric", "Learning", "A semantic table makes evaluation criteria and levels explicit.", Heading + "<div class=\"table-scroll\"><table><thead><tr><th>Criterion</th><th>Developing</th><th>Confident</th></tr></thead><tbody>@foreach(var row in Rows){<tr><th scope=\"row\">@Cell(row,0)</th><td>@Cell(row,1)</td><td>@Cell(row,2)</td></tr>}</tbody></table></div>", "Clarity|The intent needs explanation|The intent is immediately clear\nEvidence|Few supporting examples|Relevant, well-chosen examples\nReflection|Describes the outcome|Explains decisions and next steps"),
        new("worked-example", "Worked example", "Learning", "An ordered explanation followed by a clearly separated result.", Heading + "<ol class=\"worked-example\">@foreach(var row in Rows){<li><strong>@Cell(row,0)</strong><p>@Cell(row,1)</p></li>}</ol><aside class=\"notice success\">Result: each part can be checked independently.</aside>", "Define the variables|Write down what is known and what is unknown.\nChoose a method|Select a rule that connects those variables.\nCheck the result|Verify units, magnitude, and assumptions."),
        new("practice-exercise", "Practice exercise", "Learning", "A prompt with a native expandable hint and sample solution.", "<section class=\"exercise panel\"><p class=\"kicker\">Practice</p><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p>@foreach(var row in Rows){<details><summary>@Cell(row,0)</summary><p>@Cell(row,1)</p></details>}</section>", "Hint|Start with the simplest possible case.\nSample approach|Sketch a small example, test one assumption, and record what changes."),
        new("reading-list", "Annotated reading list", "Learning", "A reference list with a reason to read each item.", Heading + "<ol class=\"reading-list\">@foreach(var row in Rows){<li><a href=\"@Context.Text(\"url\")\"><cite>@Cell(row,0)</cite></a><p>@Cell(row,1)</p></li>}</ol>", "A field guide to observation|Practical exercises for looking closely.\nPatterns in everyday systems|An introduction to relationships and feedback.\nNotes on making|A thoughtful account of iteration and craft."),
        new("knowledge-check", "Knowledge check", "Learning", "A self-check question with local answer feedback in an interactive Work.", Heading + "<fieldset><legend>Which step comes before publishing?</legend><div class=\"pills\"><button @onclick=\"Correct\">Review</button><button @onclick=\"Retry\">Gather</button></div></fieldset><output aria-live=\"polite\">@answer</output>", Code: "private string answer=\"Choose an answer.\"; private void Correct()=>answer=\"Correct — review the result first.\"; private void Retry()=>answer=\"Try again. Gather material before composing.\";"),
        new("research-question", "Research question", "Learning", "A central question with the evidence needed to investigate it.", "<aside class=\"research-question\"><span class=\"kicker\">The question</span><h2>@Context.Text(\"title\")</h2><p>@Context.Text(\"text\")</p><ul>@foreach(var row in Rows){<li>@Cell(row,0)</li>}</ul></aside>", "What can we observe directly?\nWhich assumptions should we test?\nWhat would change our conclusion?"),

        new("percentage-calculator", "Percentage calculator", "Tools", "A small local calculator for a percentage of a quantity.", Heading + "<div class=\"parallel\"><label>Percentage<input type=\"number\" @bind=\"percent\" @bind:event=\"oninput\" /></label><label>Of amount<input type=\"number\" @bind=\"amount\" @bind:event=\"oninput\" /></label></div><output class=\"tool-result\">@percent% of @amount = @((amount*percent/100).ToString(\"0.##\"))</output>", Code: "private decimal percent=15, amount=240;"),
        new("unit-converter", "Distance converter", "Tools", "Convert kilometers to miles locally, without a network call.", Heading + "<label>Kilometers<input type=\"number\" min=\"0\" step=\"0.1\" @bind=\"kilometers\" @bind:event=\"oninput\" /></label><output class=\"tool-result\">@((kilometers*0.621371m).ToString(\"0.###\")) miles</output>", Code: "private decimal kilometers=10;"),
        new("aspect-ratio", "Aspect-ratio calculator", "Tools", "Calculate a matching height for a chosen width and ratio.", Heading + "<div class=\"parallel\"><label>Width<input type=\"number\" min=\"1\" @bind=\"width\" /></label><label>Ratio<select @bind=\"ratio\"><option value=\"1\">1:1</option><option value=\"1.333333333\">4:3</option><option value=\"1.777777778\">16:9</option></select></label></div><output class=\"tool-result\">@width × @Math.Round(width/Math.Max(ratio,0.01m))</output>", Code: "private decimal width=1200, ratio=1.777777778m;"),
        new("color-swatch", "Color swatch tool", "Tools", "Choose a color with the browser's native picker and inspect its value.", Heading + "<label>Color<input type=\"color\" @bind=\"color\" @bind:event=\"oninput\" /></label><div class=\"color-preview\" style=\"background:@color\"></div><output>@color</output>", Code: "private string color=\"#53766a\";"),
        new("word-count", "Word count", "Tools", "Count words and estimate reading time in a local text draft.", Heading + "<label>Draft<textarea rows=\"6\" @bind=\"draft\" @bind:event=\"oninput\"></textarea></label><output>@Words words · @draft.Length characters · @Math.Max(1,(int)Math.Ceiling(Words/200d)) minute read</output>", Code: "private string draft=\"Begin with a thought worth sharing.\"; private int Words=>draft.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Length;"),
        new("budget-calculator", "Budget remainder", "Tools", "Compare a planned budget with spending and show the remainder.", Heading + "<div class=\"parallel\"><label>Budget<input type=\"number\" min=\"0\" @bind=\"budget\" /></label><label>Spent<input type=\"number\" min=\"0\" @bind=\"spent\" /></label></div><output class=\"tool-result\">@(budget-spent) remaining</output><meter min=\"0\" max=\"@Math.Max(1,budget)\" value=\"@Math.Clamp(spent,0,Math.Max(1,budget))\">@spent of @budget</meter>", Code: "private decimal budget=1000,spent=375;"),
        new("decision-matrix", "Decision matrix", "Tools", "Compare options against explicit criteria in a compact, editable table.", Heading + "<div class=\"table-scroll\"><table><thead><tr><th>Criterion</th><th>Option A</th><th>Option B</th></tr></thead><tbody>@foreach(var row in Rows){<tr><th>@Cell(row,0)</th><td>@Cell(row,1)</td><td>@Cell(row,2)</td></tr>}</tbody></table></div><p>Use the criteria that matter to this project; scores are illustrative.</p>", "Clarity|5|4\nFlexibility|3|5\nMaintenance|5|3"),
        new("tally", "Tally counter", "Tools", "A reversible local tally with increment, decrement, and reset controls.", Heading + "<output class=\"tool-result\" aria-live=\"polite\">@count</output><div class=\"pills\"><button aria-label=\"Subtract one\" @onclick=\"()=>count--\">−</button><button aria-label=\"Add one\" @onclick=\"()=>count++\">+</button><button @onclick=\"()=>count=0\">Reset</button></div>", Code: "private int count;"),
        new("temperature-converter", "Temperature converter", "Tools", "Convert Celsius to Fahrenheit with a transparent local calculation.", Heading + "<label>Celsius<input type=\"number\" step=\"0.1\" @bind=\"celsius\" @bind:event=\"oninput\" /></label><output class=\"tool-result\">@((celsius*9/5+32).ToString(\"0.#\")) °F</output>", Code: "private decimal celsius=20;"),
        new("checklist-progress", "Checklist progress", "Tools", "An interactive local checklist with a completion total.", Heading + "<div>@for(var i=0;i<Rows.Length;i++){var index=i;<label class=\"inline\"><input type=\"checkbox\" checked=\"@done.Contains(index)\" @onchange=\"()=>Toggle(index)\" /> @Cell(Rows[i],0)</label>}</div><progress value=\"@done.Count\" max=\"@Math.Max(1,Rows.Length)\">@done.Count</progress><output>@done.Count of @Rows.Length complete</output>", "Define the question\nCollect the evidence\nMake a first draft\nReview and refine", "private HashSet<int> done=[]; private void Toggle(int i){if(!done.Add(i))done.Remove(i);}")
    ];

    private const string Css = """
        .catalog-module{--line:color-mix(in srgb,var(--hl-ink,#172a32) 18%,transparent);color:var(--hl-ink,#172a32);font-family:var(--hl-font,system-ui,sans-serif);line-height:1.65;max-width:100%;overflow-wrap:anywhere;padding:clamp(1rem,3vw,2rem)}
        h2,h3,p,figure,blockquote,dl,ul,ol{margin:0 0 1rem}h2{font-family:var(--hl-heading-font,Georgia,serif);font-size:clamp(1.5rem,3vw,2.35rem);line-height:1.15;letter-spacing:-.025em}h3{font-size:1.05rem;line-height:1.35}header{margin-bottom:1.8rem}header p,small{color:var(--hl-muted,#637079)}small{display:block;font-size:.8rem}a{color:var(--hl-accent,#53766a);text-underline-offset:4px}a:hover{text-decoration-thickness:2px}button,.action{display:inline-flex;gap:.65rem;align-items:center;border:1px solid var(--line);background:var(--hl-accent,#53766a);color:var(--hl-background,#fff);padding:.7rem 1rem;border-radius:.45rem;font:inherit;cursor:pointer;text-decoration:none}button:hover{filter:brightness(.9)}button[aria-pressed=true],[aria-current=page]{outline:2px solid var(--hl-accent,#53766a);outline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--hl-accent,#53766a);outline-offset:4px}
        .panel,details{padding:1.4rem;border:1px solid var(--line);border-radius:.65rem;background:var(--hl-surface,#f4f6f5)}details+details{margin-top:.6rem}summary{cursor:pointer;font-weight:600}details p{margin-top:1rem}.parallel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}.three-columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}.kicker{text-transform:uppercase;letter-spacing:.14em;font-size:.72rem;font-weight:700;color:var(--hl-accent,#53766a)}.lead{font-size:1.4rem;line-height:1.6;max-width:52ch}.dropcap:first-letter{float:left;font-size:4.5rem;line-height:.85;padding:.12em .12em 0 0;font-family:Georgia,serif;color:var(--hl-accent,#53766a)}.quotation{border-left:3px solid var(--hl-accent,#53766a);padding:1rem 2rem}.quotation blockquote{font:italic 1.9rem/1.4 Georgia,serif}.epigraph{max-width:36ch;margin:auto;font:italic 1.25rem/1.7 Georgia,serif}.poetry{font:1.25rem/1.8 Georgia,serif}.poetry p{margin:0}.footnotes{font-size:.85rem;border-top:1px solid var(--line);padding-top:1rem}dt{font-weight:650}dd{margin:0 0 1rem}.transcript>div{display:grid;grid-template-columns:5rem 1fr;gap:1rem}.transcript time{font-family:monospace}.byline,.cart-line,.availability,.connection-status{display:flex;gap:1rem;align-items:center}.byline p,.cart-line h3{margin:0}.avatar{display:grid;place-items:center;width:3rem;height:3rem;border-radius:50%;background:var(--hl-accent,#53766a);color:white}.avatar.large{width:5rem;height:5rem;font-size:2rem;margin:0 auto 1rem}.profile{text-align:center}
        .breadcrumbs,.pills,.pagination,.alphabet,.tags{list-style:none;display:flex;gap:.65rem;flex-wrap:wrap;padding:0;margin:0 0 1rem}.breadcrumbs li{display:inline}.pills a,.pagination a,.alphabet a,.tags li{display:inline-block;padding:.45rem .75rem;border:1px solid var(--line);border-radius:.35rem;text-decoration:none}.alphabet a{min-width:2.6rem;text-align:center}.steps{counter-reset:step;display:grid;grid-template-columns:repeat(auto-fit,minmax(10rem,1fr));gap:1.3rem;list-style:none;padding:0}.steps li:before{counter-increment:step;content:counter(step,decimal-leading-zero);display:block;color:var(--hl-accent,#53766a);font:2rem Georgia,serif;border-bottom:1px solid var(--line);margin-bottom:1rem}.link-directory a{display:grid;grid-template-columns:1fr auto;padding:1rem 0;border-bottom:1px solid var(--line);text-decoration:none}.link-directory span{grid-column:1;color:var(--hl-muted,#637079)}.link-directory b{grid-column:2;grid-row:1/3}.previous-next{display:flex;justify-content:space-between;gap:2rem}.previous-next a{flex:1;text-decoration:none}.previous-next a:last-child{text-align:right}.previous-next strong{display:block}
        label{display:flex;flex-direction:column;gap:.35rem;margin:0 0 1rem;font-size:.9rem;font-weight:600}input:not([type=checkbox]):not([type=radio]),textarea,select{box-sizing:border-box;max-width:100%;width:100%;min-height:2.7rem;padding:.65rem .8rem;border:1px solid var(--line);border-radius:.35rem;background:var(--hl-background,#fff);color:inherit;font:inherit}input[type=checkbox],input[type=radio]{accent-color:var(--hl-accent,#53766a);width:1.15rem;height:1.15rem}.inline{display:flex;flex-direction:row;align-items:center;gap:.7rem;font-weight:400}.inline input{flex-shrink:0}fieldset{border:1px solid var(--line);border-radius:.5rem;padding:1.5rem;min-width:0}legend{font-weight:650;padding:0 .5rem}output{display:block;margin-top:1rem;font-variant-numeric:tabular-nums}form button{margin-top:.5rem}.dropzone{align-items:center;text-align:center;border:2px dashed var(--line);border-radius:.6rem;padding:2rem}.dropzone>span{font-size:2rem}.dropzone input{max-width:24rem}.statistics{display:grid;grid-template-columns:repeat(auto-fit,minmax(10rem,1fr));gap:1.2rem}.statistics dt{font-size:.8rem;font-weight:400}.statistics dd,.metric>strong{display:block;font:3rem/1.3 Georgia,serif;margin:0;color:var(--hl-accent,#53766a)}.badge{display:inline-block;border:1px solid var(--line);border-radius:2rem;padding:.2rem .7rem;font-size:.75rem}.bars label{display:grid;grid-template-columns:6rem 1fr 3rem;gap:1rem;align-items:center}meter,progress{width:100%;height:1rem;accent-color:var(--hl-accent,#53766a)}.donut{width:11rem;height:11rem;margin:1rem auto;display:grid;place-items:center;border-radius:50%;background:conic-gradient(var(--hl-accent,#53766a) 0 72%,var(--line) 72% 100%)}.donut strong{display:grid;place-content:center;text-align:center;background:var(--hl-background,#fff);border-radius:50%;width:8.5rem;height:8.5rem;font-size:2rem}.center{text-align:center}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.9rem}th,td{text-align:left;padding:.85rem;border-bottom:1px solid var(--line)}thead th{background:var(--hl-surface,#f4f6f5)}caption{text-align:left;font-weight:600;margin-bottom:.6rem}.ranking{padding-left:2rem}.ranking li{padding:.9rem;border-bottom:1px solid var(--line)}.ranking span{float:right;font-variant-numeric:tabular-nums}.timeline{list-style:none;padding:0 0 0 1.5rem;border-left:1px solid var(--hl-accent,#53766a)}.timeline li{position:relative;margin:0 0 2rem}.timeline li:before{content:'';position:absolute;left:-1.8rem;top:.5rem;width:.5rem;height:.5rem;background:var(--hl-accent,#53766a);border-radius:50%}.timeline time{font-size:.75rem;color:var(--hl-accent,#53766a)}.agenda>div,.record>div{display:grid;grid-template-columns:1fr 2fr;gap:1rem;border-bottom:1px solid var(--line);padding:.65rem 0}.agenda dd,.record dd{margin:0}.agenda time{display:block;font-size:.8rem}.task{border:1px solid var(--line);padding:.7rem;margin:.65rem 0;border-radius:.3rem;background:var(--hl-background,#fff)}.total{display:flex;justify-content:space-between;font-size:1.2rem;border-top:2px solid var(--line);padding-top:1rem}
        .product-art{display:grid;place-items:center;background:linear-gradient(135deg,var(--hl-surface,#e7eeeb),color-mix(in srgb,var(--hl-accent,#53766a) 25%,transparent));height:10rem;border-radius:.5rem;font-size:4rem;margin-bottom:1rem}.product-art.small{height:4rem;width:4rem;font-size:2rem;flex-shrink:0;margin:0}.price{display:block;font-size:2rem;margin:1rem 0}.price small{display:inline;font-size:.85rem}.cart-line label{max-width:6rem;margin:0}.pricing ul{list-style:none;padding:0}.pricing li{padding:.5rem 0}.receipt{max-width:30rem;margin:auto;text-align:center;border:1px solid var(--line);padding:2rem}.receipt .record{text-align:left}.seal{display:grid;place-items:center;margin:0 auto 1rem;border:1px solid var(--hl-accent,#53766a);border-radius:50%;width:3rem;height:3rem}.status-dot{width:.7rem;height:.7rem;border-radius:50%;background:#357654;flex-shrink:0}.availability .action{margin-left:auto}.feature-checklist{padding:0;list-style:none}.feature-checklist li{display:flex;gap:1rem}.feature-checklist span{color:var(--hl-accent,#53766a)}.testimonial blockquote{font:italic 1.35rem/1.6 Georgia,serif}.chapter-cover{padding:2rem 0}.chapter-cover h2{font-size:clamp(2rem,5vw,4rem)}.chapter-number{font:5rem/1 Georgia,serif;color:var(--hl-accent,#53766a);opacity:.65}.split-intro{align-items:center}.split-intro h2{font-size:clamp(2rem,5vw,4rem)}.aside-note{max-width:35rem;border-left:3px solid var(--hl-accent,#53766a);padding:0 1.5rem}.section-heading{padding-bottom:1rem;border-bottom:1px solid var(--line)}.newsletter{display:flex;gap:2rem;align-items:center}.newsletter .action{flex-shrink:0}.call-to-action{text-align:center;padding:2rem;background:var(--hl-surface,#f4f6f5);border-radius:.6rem}hr{border:0;border-top:1px solid var(--line);margin:1.5rem 0}
        .ornamental-rule{display:flex;align-items:center;gap:1.5rem;color:var(--hl-accent,#53766a)}.ornamental-rule:before,.ornamental-rule:after{content:'';height:1px;background:var(--line);flex:1}.corner-frame{position:relative;padding:2rem;text-align:center}.corner-frame:before,.corner-frame:after{content:'';position:absolute;width:2rem;height:2rem;border-color:var(--hl-accent,#53766a)}.corner-frame:before{top:0;left:0;border-top:1px solid;border-left:1px solid}.corner-frame:after{bottom:0;right:0;border-bottom:1px solid;border-right:1px solid}.edition-seal{border:3px double var(--hl-accent,#53766a);border-radius:50%;width:10rem;height:10rem;display:flex;flex-direction:column;justify-content:center;text-align:center;margin:auto;padding:1rem}.edition-seal span{font-size:2rem}.edition-seal strong{text-transform:uppercase;letter-spacing:.08em}.dot-grid{padding:2rem;background-image:radial-gradient(var(--line) 1px,transparent 1px);background-size:12px 12px}.numbered-marker{display:flex;gap:1.5rem;align-items:center}.numbered-marker>span{font:4rem Georgia,serif;color:var(--hl-accent,#53766a)}.ribbon{display:inline-block;background:var(--hl-accent,#53766a);color:var(--hl-background,#fff);padding:.5rem 2rem .5rem 1rem;clip-path:polygon(0 0,100% 0,calc(100% - 1rem) 50%,100% 100%,0 100%);margin-bottom:1rem}.reading-progress span{display:flex;justify-content:space-between;gap:1rem}.tags li{border-radius:2rem;font-size:.8rem}.inset-paper{box-shadow:5px 5px 0 var(--line);border:1px solid var(--line);padding:2rem;background:var(--hl-surface,#f4f6f5)}.accent-band{display:flex;gap:1rem;flex-wrap:wrap;background:var(--hl-accent,#53766a);color:var(--hl-background,#fff);padding:1rem 1.5rem}.empty-state{text-align:center;padding:3rem 1rem}.empty-state>span{font-size:4rem;color:var(--hl-accent,#53766a)}.notice{display:flex;gap:1rem;padding:1.5rem;border-left:3px solid var(--hl-accent,#53766a);background:var(--hl-surface,#f4f6f5)}.notice h2{font-size:1.2rem}.notice p{margin:0}.notice.error{display:block;border-color:#a74535}.notice.warning{border-color:#9a6b26}.notice.success{border-color:#357654}.skeleton div,.skeleton p{background:var(--line);border-radius:.4rem;min-height:1rem;max-width:90%}.skeleton div{height:7rem;max-width:100%}.skeleton p:last-of-type{max-width:60%}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.revisions{list-style:none;padding:0}.revisions li{display:flex;align-items:flex-start;gap:1rem;margin:1rem 0}.offline-note{display:flex;gap:1rem;border:1px dashed var(--line);padding:1.2rem}.offline-note p{margin:0}.offline-note>span{font-size:2rem}.flashcard h3{font:1.6rem Georgia,serif}.objectives li{padding:.6rem}.lesson-outline{list-style:none;padding:0}.lesson-outline li{display:grid;grid-template-columns:4rem 1fr;gap:1rem;margin-bottom:1rem}.experiment dt{text-transform:uppercase;font-size:.7rem;letter-spacing:.1em;color:var(--hl-accent,#53766a)}.experiment dd{padding:.5rem 0 1rem;border-bottom:1px solid var(--line)}.worked-example li{padding:.5rem}.research-question{border:2px solid var(--hl-accent,#53766a);padding:2rem}.tool-result{font:2rem/1.4 Georgia,serif;padding:1rem 0;color:var(--hl-accent,#53766a)}.color-preview{height:6rem;border:1px solid var(--line);border-radius:.5rem}.connection-status small{margin-left:auto}
        @media(max-width:600px){.parallel,.three-columns{grid-template-columns:1fr}.newsletter,.cart-line,.availability{flex-wrap:wrap}.bars label{grid-template-columns:5rem 1fr 2.5rem}.catalog-module{padding:.9rem}.transcript>div{grid-template-columns:3.5rem 1fr}.statistics{grid-template-columns:1fr}.previous-next{gap:1rem}.chapter-cover h2{font-size:2.5rem}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
